// The backdrop of a skin imported from Codex Dream Skin: the theme's picture behind the conversation, a veil that is
// strongest over the reading column, a ground under a docked side area, and on an empty page the theme's quote.
// It also draws the figure of the agent (shell.piece figure) and the floating companion (session.companion.figure)
// as a round medallion cut from the picture at its focus.
//
// Generated by scripts/import-dream-skin.mjs from templates/dream/draw/dream.js; the scene below is the only part that
// differs between skins. Nothing is imported: React and the file addresses are what the host hands in, and every look
// is an inline style (the page's CSP allows no <style> element).

const SCENE = /*SCENE*/ {}

// Light or dark as the app resolved it: <html data-theme="light|dark">, else the system.
const root = () => (typeof document === 'undefined' ? undefined : document.documentElement)
const systemDark = () => typeof matchMedia === 'function' && matchMedia('(prefers-color-scheme: dark)').matches
const isDark = () => {
  const theme = root()?.dataset.theme
  return theme === undefined || theme === '' ? systemDark() : theme === 'dark'
}
function onTheme(change) {
  const element = root()
  if (element === undefined) return () => {}
  const watch = new MutationObserver(change)
  watch.observe(element, { attributes: true, attributeFilter: ['data-theme'] })
  const system = typeof matchMedia === 'function' ? matchMedia('(prefers-color-scheme: dark)') : undefined
  system?.addEventListener('change', change)
  return () => {
    watch.disconnect()
    system?.removeEventListener('change', change)
  }
}

// The reading column of the conversation when no composer is there to measure (session-ui: 185 steps of 4px).
const COLUMN = 740
const layer = { position: 'absolute', inset: 0 }
const fade = 'opacity 600ms cubic-bezier(0.2, 0.8, 0.2, 1)'

// Parts of the page the backdrop reads to know where the words are. All three are OMNE parts (data-omne-part).
const PART = name => `[data-omne-part="${name}"]`
const SIDE_OPEN = `${PART('session.side')}[data-presentation="docked"][data-open="true"]`

/** Where the reading column and a docked side area sit, in the backdrop's own coordinates; null where there is none. */
function layoutOf(hall) {
  const page = hall.parentElement?.parentElement ?? hall.ownerDocument
  const at = hall.getBoundingClientRect()
  const composer = page.querySelector(PART('session.composer'))?.getBoundingClientRect()
  const transcript = page.querySelector(PART('session.transcript'))?.getBoundingClientRect()
  const side = page.querySelector(SIDE_OPEN)?.getBoundingClientRect()
  let column = null
  if (composer !== undefined && composer.width > 0) column = { left: composer.left - at.left, right: composer.right - at.left }
  else if (transcript !== undefined && transcript.width > 0) {
    const wide = Math.min(COLUMN, transcript.width)
    const left = transcript.left - at.left + (transcript.width - wide) / 2
    column = { left, right: left + wide }
  }
  const docked =
    side !== undefined && side.width > 1
      ? { left: side.left - at.left, top: side.top - at.top, width: side.width, height: side.height }
      : null
  const round = box => (box === null ? null : Object.fromEntries(Object.entries(box).map(([k, v]) => [k, Math.round(v)])))
  return { width: Math.round(at.width), height: Math.round(at.height), column: round(column), side: round(docked) }
}
const sameLayout = (a, b) => JSON.stringify(a) === JSON.stringify(b)

const rgb = hex => [1, 3, 5].map(i => Number.parseInt(hex.slice(i, i + 2), 16)).join(' ')
const groundOf = dark => (dark ? SCENE.ground.dark : SCENE.ground.light)
const tintOf = (dark, alpha) => `rgb(${rgb(groundOf(dark))} / ${alpha}%)`

/**
 * The veil: in the mode the picture was made for it only keeps the words readable; in the other mode it washes the
 * picture toward that mode's ground, so a dark painting under a light interface reads as a soft print, not a hole.
 */
function veilOf(dark, empty, { width, column }) {
  const own = SCENE.mode === (dark ? 'dark' : 'light')
  const tint = alpha => tintOf(dark, alpha)
  if (empty) return `linear-gradient(180deg, ${tint(own ? 6 : 52)} 0%, ${tint(own ? 24 : 64)} 100%)`
  const edge = tint(own ? 18 : 58)
  const strong = tint(own ? 72 : 86)
  if (column === null || width === 0) return `linear-gradient(90deg, ${edge} 0%, ${strong} 30%, ${strong} 70%, ${edge} 100%)`
  const soft = 72
  return `linear-gradient(90deg, ${edge} 0px, ${strong} ${Math.max(0, column.left - soft)}px, ${strong} ${column.right + soft}px, ${edge} ${width}px)`
}

/** The ground under a docked side area, so what it shows reads over the picture. */
const sideGround = (dark, side) => ({
  position: 'absolute',
  left: side.left,
  top: side.top,
  width: side.width,
  height: side.height,
  background: tintOf(dark, 90),
  boxShadow: `inset 1px 0 0 rgb(${rgb(dark ? SCENE.accent.dark : SCENE.accent.light)} / 30%)`,
})

/** The theme's quote and name, low in the corner of an empty page, as the Dream home page has them. */
const quoteOf = (h, dark) =>
  h(
    'div',
    {
      key: 'quote',
      style: {
        position: 'absolute',
        right: 'calc(var(--omne-size) * 40px)',
        bottom: 'calc(var(--omne-size) * 32px)',
        maxWidth: '40%',
        textAlign: 'right',
        color: dark ? SCENE.accent.dark : SCENE.accent.light,
        fontFamily: 'var(--omne-font-reading)',
        fontStyle: 'italic',
        fontSize: 'calc(var(--omne-size) * 22px)',
        letterSpacing: '0.08em',
        transform: 'rotate(-3deg)',
        opacity: 0.85,
        textShadow: `0 1px 12px ${tintOf(dark, 80)}`,
        userSelect: 'none',
      },
    },
    SCENE.quote,
    SCENE.name === ''
      ? null
      : h('div', { style: { fontSize: '0.55em', fontStyle: 'normal', letterSpacing: '0.2em', marginTop: '0.4em', opacity: 0.8 } }, SCENE.name),
  )

export const backdrop = ({ React, files }) => {
  const h = React.createElement
  const picture = files?.url(SCENE.image)

  function Scene({ part, empty }) {
    const dark = React.useSyncExternalStore(onTheme, isDark, () => false)
    const place = React.useRef(null)
    const [box, setBox] = React.useState({ width: 0, height: 0, column: null, side: null })
    React.useLayoutEffect(() => {
      const hall = place.current
      if (hall === null || typeof ResizeObserver === 'undefined') return undefined
      const sized = new ResizeObserver(() => schedule())
      let frame = 0
      const measure = () => {
        frame = 0
        const next = layoutOf(hall)
        setBox(now => (sameLayout(now, next) ? now : next))
        // Follow the parts it read as they resize (the side area slides open, the window narrows).
        const page = hall.parentElement?.parentElement
        for (const name of [PART('session.composer'), PART('session.transcript'), SIDE_OPEN]) {
          const found = page?.querySelector(name)
          if (found) sized.observe(found)
        }
      }
      const schedule = () => {
        if (frame === 0) frame = requestAnimationFrame(measure)
      }
      measure()
      sized.observe(hall)
      // A session opened or closed, or the side area opened: the parts come and go under the page.
      const page = hall.parentElement?.parentElement
      const changed = typeof MutationObserver === 'undefined' || page == null ? undefined : new MutationObserver(schedule)
      changed?.observe(page, { subtree: true, childList: true, attributes: true, attributeFilter: ['data-open'] })
      return () => {
        if (frame !== 0) cancelAnimationFrame(frame)
        sized.disconnect()
        changed?.disconnect()
      }
    }, [])
    return h(
      'div',
      { ...part, ref: place, style: { ...layer, overflow: 'hidden', background: groundOf(dark) } },
      h('div', {
        key: 'picture',
        style: {
          ...layer,
          backgroundImage: `url("${picture}")`,
          backgroundSize: 'cover',
          backgroundPosition: `${SCENE.focusX * 100}% ${SCENE.focusY * 100}%`,
        },
      }),
      h('div', { key: 'veil', style: { ...layer, backgroundImage: veilOf(dark, empty, box), transition: fade } }),
      !empty && box.side !== null ? h('div', { key: 'side', style: sideGround(dark, box.side) }) : null,
      empty && SCENE.quote !== '' ? quoteOf(h, dark) : null,
    )
  }

  return ({ part, props, builtIn }) => (picture === undefined ? builtIn() : h(Scene, { part, empty: props?.empty === true }))
}

const lessMotion = () => typeof matchMedia === 'function' && matchMedia('(prefers-reduced-motion: reduce)').matches

/** The theme's medallion, cut round from the picture at its focus: ringed in the accent, bobbing while the agent works. */
function medallionOf(React) {
  const h = React.createElement
  return function Medallion({ src, size, busy, lifted, part }) {
    const face = React.useRef(null)
    const dark = React.useSyncExternalStore(onTheme, isDark, () => false)
    React.useEffect(() => {
      const element = face.current
      if (!busy || element === null || typeof element.animate !== 'function' || lessMotion()) return undefined
      const bob = element.animate(
        [{ transform: 'translateY(0)' }, { transform: 'translateY(-6%)' }, { transform: 'translateY(0)' }],
        { duration: 1400, iterations: Infinity, easing: 'ease-in-out' },
      )
      return () => bob.cancel()
    }, [busy])
    const accent = dark ? SCENE.accent.dark : SCENE.accent.light
    return h(
      'span',
      {
        ...part,
        style: {
          display: 'inline-flex',
          width: size,
          height: size,
          transform: lifted ? 'scale(1.08) rotate(-4deg)' : 'none',
          transition: 'transform 180ms cubic-bezier(0.2, 0.8, 0.2, 1)',
          pointerEvents: 'none',
        },
      },
      h('img', {
        ref: face,
        src,
        alt: '',
        draggable: false,
        width: size,
        height: size,
        style: {
          width: '100%',
          height: '100%',
          borderRadius: '50%',
          objectFit: 'cover',
          boxShadow: `0 0 0 2px ${accent}, 0 3px 8px rgb(0 0 0 / 30%)`,
          userSelect: 'none',
        },
      }),
    )
  }
}

/** shell.piece figure: the agent's figure, in the sidebar's home or flying, as the theme's medallion. */
export const figure = ({ React, files }) => {
  const Medallion = medallionOf(React)
  const src = files?.url(SCENE.figure)
  return ({ subject, generic }) => {
    if (src === undefined) return generic()
    const busy = subject?.doing !== undefined && subject.doing !== 'idle' && subject.doing !== 'background'
    return React.createElement(Medallion, { src, size: subject?.size ?? 48, busy, lifted: subject?.hover === true })
  }
}

/** session.companion.figure: the floating companion, the same medallion, a little larger and lifted while carried. */
export const companion = ({ React, files }) => {
  const Medallion = medallionOf(React)
  const src = files?.url(SCENE.figure)
  return ({ part, props, builtIn }) => {
    if (src === undefined) return builtIn()
    const busy = props?.doing !== undefined && props.doing !== 'idle' && props.doing !== 'background'
    return React.createElement(Medallion, { part, src, size: 56, busy, lifted: props?.dragging === true || props?.unfolded === true })
  }
}
